import { checkedAttributionSupports } from '/home/edge/projects/rezics/rezics-next/.temp/worktrees/g-2781/.temp/candidates/retained-source/services/main/src/modules/relation/v2-schema.ts';
import { InvalidRelationOccurrence } from '/home/edge/projects/rezics/rezics-next/.temp/worktrees/g-2781/.temp/candidates/retained-source/services/main/src/modules/relation/schema.ts';

const ref = 'https://rezics.com/id/12345678-1234-1234-1234-123456789abc';
const input = (basis: unknown) => [{ basis, fields: ['creditedName'], evidence: ['https://example.test/citation'] }];

test('the four declared attribution basis kinds keep their native owner references', () => {
  for (const basis of [
    { kind: 'source-credit', support: ref },
    { kind: 'native-credit', credit: ref, revision: ref },
    { kind: 'source-binding', binding: ref },
    { kind: 'selected-publication', decision: ref },
  ]) expect(checkedAttributionSupports(input(basis))).toEqual(input(basis));
});

for (const kind of ['unknown', '', 'constructor', '__proto__', 'toString']) {
  test(`unsupported attribution basis ${JSON.stringify(kind)} returns the native validation refusal`, () => {
    let result: unknown = null;
    try { checkedAttributionSupports(input({ kind })); }
    catch (error) { result = error; }
    expect(result).toBeInstanceOf(InvalidRelationOccurrence);
  });
}

